/**
 * Typed access to the generated token distribution.
 *
 * Components read values from here rather than hard-coding them, which is
 * what lets the annotation layer display real numbers: a measurement mark
 * that says 64 says it because `space.16` is 64, not because someone typed
 * 64 into a mark.
 *
 * public/tokens.json is generated by `npm run tokens` and committed.
 */
import dist from "@/public/tokens.json";

type Scheme = "light" | "dark";

export const tokens = dist;

/* ----------------------------------------------------------------- space -- */

const spaceEntries = Object.entries(dist.space).filter(
  ([k, v]) => !k.startsWith("$") && typeof v === "number"
) as [string, number][];

export const spaceScale = spaceEntries
  .map(([step, px]) => ({ step: Number(step), px, name: `--space-${step}` }))
  .sort((a, b) => a.px - b.px);

/** space(16) -> 64. Throws at build time if the step is not on the scale. */
export function space(step: number): number {
  const found = spaceScale.find((s) => s.step === step);
  if (!found) {
    throw new Error(
      `space(${step}) is not on the scale. Legal steps: ${spaceScale.map((s) => s.step).join(", ")}`
    );
  }
  return found.px;
}

export const spaceVar = (step: number) => `var(--space-${step})`;

/* ------------------------------------------------------------------ type -- */

export const typeScale = (
  Object.entries(dist.type.size) as [string, number][]
)
  .map(([step, px]) => ({ step: Number(step), px, name: `--size-${step}` }))
  .sort((a, b) => a.px - b.px);

export const typeMeta = {
  ratio: dist.type.$ratio,
  base: dist.type.$base,
  leading: dist.type.leading,
  measure: dist.type.measure.value,
  family: dist.type.family,
  width: dist.type.width,
};

/* ---------------------------------------------------------------- colour -- */

export const primitiveColors = Object.entries(dist.color).map(([name, def]) => ({
  name,
  cssVar: `--${name}`,
  value: def.value,
  role: def.role,
}));

export type SemanticToken = {
  name: string;
  cssVar: string;
  light: string;
  dark: string;
  /** How the value was arrived at: an alias, a blend, or a solved contrast. */
  origin: string;
  kind: "alias" | "mix" | "solved";
  /** What the role is for, which decides how it is contrast-checked. */
  use: string;
  /** Contrast against the role's own reference, per scheme. Null for surfaces. */
  lightContrast: number | null;
  darkContrast: number | null;
  contrastAgainst: string | null;
  required: number | null;
};

type DistEntry = {
  value: string;
  origin: string;
  kind: SemanticToken["kind"];
  use: string;
  contrast: number | null;
  contrastAgainst: string | null;
  required: number | null;
};

const scheme = (name: Scheme) => dist.semantic[name] as unknown as Record<string, DistEntry>;

export const semanticColors: SemanticToken[] = Object.keys(dist.semantic.light)
  .filter((name) => !name.startsWith("$"))
  .map((name) => {
    const light = scheme("light")[name];
    const dark = scheme("dark")[name];
    return {
      name,
      cssVar: `--c-${name}`,
      light: light.value,
      dark: dark.value,
      origin: light.origin,
      kind: light.kind,
      use: light.use,
      lightContrast: light.contrast,
      darkContrast: dark.contrast,
      contrastAgainst: light.contrastAgainst,
      required: light.required,
    };
  });

/** The contrast contract the token build enforces on every run. */
export const a11yTargets = dist.$a11y;

/* ------------------------------------------------------------------ grid -- */

export const grid = dist.grid;
export const motion = dist.motion;
export const border = dist.border;
export const tokenVersion = dist.$version;
